{
  "steps": [
    "1) Triage: Confirm alert details (alert id ALT-V2-D0008, root account ACC-D0008-RT00, amount INR 4,480,723.63, rule SCATTER_GATHER) and capture timeline and immediate containment actions required.",
    "2) Flow analysis (parallel): Trace outgoing and incoming value flows from root account to identify scatter (many outflows) and gather (many inflows) counterparties, quantify split/merge patterns and time windows.",
    "3) Counterparty enrichment (parallel): Gather KYC/business registry data and historical behavior for highest-value and highest-degree counterparties identified by flow analysis.",
    "4) Pattern & conservation checks: Compute flow conservation across the subgraph(s) to detect layering, wash patterns, or rapid re-aggregation consistent with SCATTER_GATHER typology; compare alternate graph runs if needed.",
    "5) Regulatory context: Retrieve relevant statute/regulatory guidance applicable to cross-border / high-value scattering/gathering and AML thresholds for INR amounts and required reporting obligations.",
    "6) Synthesis & risk scoring: Combine transactional graph metrics, KYC risk indicators, and regulatory triggers to produce incident severity, probable typology (fraud/laundering/benign), and recommended next steps (freeze, file SAR, escalate).",
    "7) Reporting & critique: Produce final investigation brief with visual summary of fund flows, list of prioritized counterparties, recommended actions, and an internal critique assessing any data gaps or uncertainties."
  ],
  "handoffs": [
    {
      "task_id": "HO-FLOW",
      "target_agent": "flow_tracer",
      "objective": "Perform detailed transaction graph tracing from root ACC-D0008-RT00 for the relevant alert window: (a) retrieve alert context and all account transactions for root; (b) identify candidate outgoing/incoming fund flows, quantify amounts and timing; (c) produce subgraph(s) showing scatter and gather nodes, compute flow conservation and flag nodes where value disappears or concentrates; (d) produce prioritized list of top 20 counterparties by value and degree for enrichment.",
      "allowed_tool_budget": 4
    },
    {
      "task_id": "HO-BENIGN",
      "target_agent": "benign_investigator",
      "objective": "Enrich prioritized counterparties from flow_tracer: for each top counterparty, (a) retrieve KYC/profile and commercial registry entries, (b) retrieve historical transaction behavior and any prior alert involvements, (c) assess commercial plausibility of transaction patterns and produce per-counterparty risk notes and recommended follow-up (e.g., request docs, contact relationship manager).",
      "allowed_tool_budget": 5
    },
    {
      "task_id": "HO-REG",
      "target_agent": "regulatory_analyst",
      "objective": "Provide regulatory context and thresholds: (a) search applicable AML / reporting regulations and guidance relevant to INR 4,480,723.63 and SCATTER_GATHER behavior; (b) return clause references that mandate reporting, account freezing, or enhanced due diligence; (c) highlight cross-border or sanctions checks to execute if counterparties are foreign.",
      "allowed_tool_budget": 2
    },
    {
      "task_id": "HO-CRITIC",
      "target_agent": "reporter_critic",
      "objective": "Independently validate flow_tracer's conservation computations and the synthesized incident narrative: (a) recompute key flow conservation checks for the produced subgraph; (b) perform a critical review of the planned conclusions and recommended actions, flagging assumptions, data gaps, and alternative explanations; (c) produce final critique and ready-to-issue brief comments for the investigator.",
      "allowed_tool_budget": 2
    }
  ]
}

{
  "steps": [
    "1) Triage & context gathering: assign flow_tracer to fetch alert context for ALT-V2-D0045, retrieve recent transactions for root ACC-D0045-RT00, and a first-pass scatter/gather graph of immediate outgoing/incoming flows around the INR 626,624.81 alert amount.",
    "2) Rapid pattern & candidate flow discovery: flow_tracer to identify downstream/upstream candidate accounts that receive/redistribute portions of the flagged amount and produce candidate fund-flow subgraphs for follow-up.",
    "3) KYC & counterparty screening: benign_investigator to pull KYC/profile data and commercial registry records for the root and top counterparties identified by flow_tracer, and to check historical counterparty behavior for benign vs suspicious indicators.",
    "4) Flow validation & conservation checks: flow_tracer (with reporter_critic for independent check) to compute flow conservation on the candidate graphs, quantify discrepancies, and replan graph expansion to close unexplained outflows.",
    "5) Regulatory relevance assessment: regulatory_analyst to search applicable regulations and retrieve clauses relevant to scatter/gather patterns, thresholds for INR-level reporting, and reporting timeframes for potentially suspicious activity.",
    "6) Synthesis & critique: reporter_critic to independently recompute key conservation numbers, critique investigative gaps, and prepare flagged findings and recommended next steps (monitor, escalate to SAR filing, or close).",
    "7) Final consolidation: combine flow analysis, KYC findings, regulatory citations, and reporter_critic recommendations into an investigative summary for case disposition."
  ],
  "handoffs": [
    {
      "task_id": "HO-FLOW",
      "target_agent": "flow_tracer",
      "objective": "Obtain alert context for ALT-V2-D0045 and root account ACC-D0045-RT00; retrieve recent (90-day) transactions for the root and immediate counterparties; construct initial scatter/gather fund-flow graph centered on INR 626,624.81; identify top 20 candidate downstream/upstream accounts (by value and frequency) and produce candidate subgraphs for each. Deliverables: alert context, transaction extracts, candidate account list, initial graphs, and recommendations for where to expand the graph.",
      "allowed_tool_budget": 4
    },
    {
      "task_id": "HO-BENIGN",
      "target_agent": "benign_investigator",
      "objective": "For the root and the top counterparties produced by flow_tracer, fetch KYC/profile records, check commercial registry entries (business registration, directors), and compile counterparty transaction histories to spot benign commercial patterns versus red flags (rapid splitting, round-robin transfers, use of many low-value nodes). Deliverables: KYC summaries, registry checks, counterparty history notes, and a risk/benignness recommendation per counterparty.",
      "allowed_tool_budget": 5
    },
    {
      "task_id": "HO-REG",
      "target_agent": "regulatory_analyst",
      "objective": "Search regulations relevant to INR-denominated suspicious transaction reporting and gather clauses that apply to scatter/gather typologies, thresholds around INR 626,624.81, and mandated timelines. Deliverables: applicable regulation references and clause excerpts to support escalation/filing decisions.",
      "allowed_tool_budget": 2
    },
    {
      "task_id": "HO-CRITIC",
      "target_agent": "reporter_critic",
      "objective": "Independently recompute flow conservation for the candidate graphs and validate key quantitative findings; produce a concise critique highlighting gaps, confidence levels, and recommended next actions (monitor, escalate to SAR, request more data). Deliverables: independent conservation checks, confidence assessment, and final recommended disposition text for inclusion in the case report.",
      "allowed_tool_budget": 2
    }
  ]
}

