    {
      "task_id": "HO-REG",
      "target_agent": "regulatory_analyst",
      "objective": "Using up to 2 tool calls, search and extract relevant regulatory clauses and thresholds for scatter-gather typologies under applicable jurisdiction (domestic AML and payments rules for INR transactions), identify any mandatory reporting triggers given the INR 294,687.84 amount and aggregated flows, and produce citation-ready references and recommended compliance actions.",
      "allowed_tool_budget": 2
